(async function (statusCode, responseTime, responseRaw, modules) {
    if (statusCode !== 200) {
        return { status: 'DOWN', latency: responseTime };
    }
    var body;
    try { body = JSON.parse(responseRaw); }
    catch (e) { return { status: 'DOWN', latency: responseTime }; }
    // /healthcheck always returns 200 by design so a restart loop cannot form.
    // A dependency being down is DEGRADED here, not DOWN: the process is alive.
    if (body.status !== 'ok' || body.db !== true || body.redis !== true) {
        return { status: 'DEGRADED', latency: responseTime };
    }
    return { status: 'UP', latency: responseTime };
})

